/** An ad the shopper saw or clicked. */
export interface AdBlock {
  /** Ad or creative identifier. */
  id?: string;
  campaignId?: string;
  adGroupId?: string;
  /** Ad network, for example google_ads, meta, amazon_ads. */
  network?: string;
  format?: "search" | "display" | "video" | "shopping" | "sponsored_product" | "sponsored_brand" | "sponsored_display" | "social" | "retargeting" | "native" | "other";
  placement?: string;
  keyword?: string;
  targetingType?: string;
  position?: number;
}

/** A brand or brand store. */
export interface BrandBlock {
  id?: string;
  name?: string;
}

/** The shopping cart. */
export interface CartBlock {
  /** Merchant cart identifier. */
  id?: string;
  /** Cart value in currency. */
  total?: number | string;
  currency?: string;
  /** Cart lines. */
  items?: Array<{ productId: string; quantity?: number; price?: number | string; currency?: string; categoryId?: string }>;
}

/** A product category. */
export interface CategoryBlock {
  /** Merchant category identifier. */
  id?: string;
  /** Human-readable category name. */
  name?: string;
}

/** A list or placement of several products, such as a grid, carousel or promotion row. */
export interface ListBlock {
  /** Identifier of the list or placement. */
  id?: string;
  name?: string;
  /** 1-based position of the product the event is about, within the list. */
  position?: number;
  /** Products shown, in display order. */
  productIds?: Array<string>;
  /** For example search, category, best_sellers, deals, coupons, carousel. */
  type?: string;
}

/** Loyalty programme status. */
export interface LoyaltyBlock {
  tier?: string;
  previousTier?: string;
  points?: number;
  rewardId?: string;
}

/** An email, SMS, push or in-app message. */
export interface MessageBlock {
  /** Message or send identifier from the messaging tool. */
  id?: string;
  channel?: "email" | "sms" | "push" | "in_app" | "whatsapp";
  campaignId?: string;
  templateId?: string;
  /** For example newsletter, price_drop_alert, back_in_stock_alert, win_back, replenishment. */
  category?: string;
}

/** An order. Report authoritative order facts from the server. */
export interface OrderBlock {
  /** Merchant order identifier, or a hashed reference. */
  id?: string;
  /** Order total in currency. */
  total?: number | string;
  currency?: string;
  /** Order lines. */
  items?: Array<{ productId: string; quantity?: number; price?: number | string; currency?: string; categoryId?: string }>;
  tax?: number | string;
  shipping?: number | string;
  discount?: number | string;
  coupon?: string;
  fulfilmentMethod?: "merchant" | "marketplace" | "third_party_logistics" | "store_pickup" | "dropship";
  /** Marketplace or storefront, for example amazon_us or web. */
  marketplace?: string;
}

/** A payment, refund or chargeback amount. */
export interface PaymentBlock {
  id?: string;
  method?: "card" | "wallet" | "bank_transfer" | "buy_now_pay_later" | "cash_on_delivery" | "gift_card" | "store_credit" | "other";
  provider?: string;
  amount?: number | string;
  currency?: string;
  failureReason?: string;
}

/** The single product an event is about. */
export interface ProductBlock {
  /** Merchant product identifier. */
  id?: string;
  /** Selected variant (size, colour) when it differs from the product id. */
  variantId?: string;
  /** Product name as shown to the shopper. */
  name?: string;
  brand?: string;
  /** Unit price in currency. */
  price?: number | string;
  /** ISO 4217 code of price. */
  currency?: string;
  /** Units involved in this event. */
  quantity?: number;
  /** Merchant SKU. */
  sku?: string;
  /** Parent product, for example a parent ASIN or a product group. */
  parentId?: string;
}

/** A promotion, coupon or deal. */
export interface PromotionBlock {
  id?: string;
  name?: string;
  couponCode?: string;
  discount?: number | string;
  currency?: string;
  /** For example percent_off, amount_off, free_shipping, bundle. */
  type?: string;
}

/** The recommendation list an interaction came from, for attribution back to the provider that served it. */
export interface RecommendationBlock {
  /** Recommendation id issued by the provider. */
  id?: string;
  /** Who served the list, for example amazon-personalize. Attribution goes only to this provider. */
  provider?: string;
}

/** A referral. */
export interface ReferralBlock {
  code?: string;
  channel?: string;
}

/** A return. */
export interface ReturnBlock {
  id?: string;
  orderId?: string;
  reason?: "damaged_or_defective" | "wrong_item" | "not_as_described" | "poor_quality" | "size_or_fit_issue" | "late_delivery" | "changed_mind" | "duplicate_order" | "missing_parts" | "compatibility_issue" | "price_issue" | "other";
  method?: string;
  refundAmount?: number | string;
  currency?: string;
  items?: Array<{ productId: string; quantity?: number }>;
}

/** A review of a product or seller. */
export interface ReviewBlock {
  id?: string;
  rating?: number;
  hasMedia?: boolean;
  verifiedPurchase?: boolean;
  textLength?: number;
}

/** A search the shopper ran. */
export interface SearchBlock {
  /** The text searched for. */
  query?: string;
  resultsCount?: number;
}

/** A shipment of an order. */
export interface ShipmentBlock {
  id?: string;
  orderId?: string;
  carrier?: string;
  /** For example standard, express, same_day, pickup. */
  method?: string;
  estimatedDeliveryAt?: string;
  fulfilmentMethod?: "merchant" | "marketplace" | "third_party_logistics" | "store_pickup" | "dropship";
}

/** A product subscription (subscribe and save, replenishment). */
export interface SubscriptionBlock {
  id?: string;
  plan?: string;
  /** For example P1M for monthly. */
  interval?: string;
}

/** A support conversation or ticket. */
export interface SupportBlock {
  /** Ticket, conversation or call identifier. */
  id?: string;
  channel?: "chatbot" | "live_chat" | "email" | "phone" | "web_form" | "social" | "marketplace_message";
  topic?: string;
  intent?: string;
  priority?: string;
  resolution?: string;
}

/** A satisfaction survey. */
export interface SurveyBlock {
  id?: string;
  type?: "csat" | "nps" | "ces";
  score?: number;
}

/** The `data` object of an event: catalog blocks, plus inline fields a tracking plan declares. */
export interface EventData {
  ad?: AdBlock;
  brand?: BrandBlock;
  cart?: CartBlock;
  category?: CategoryBlock;
  list?: ListBlock;
  loyalty?: LoyaltyBlock;
  message?: MessageBlock;
  order?: OrderBlock;
  payment?: PaymentBlock;
  product?: ProductBlock;
  promotion?: PromotionBlock;
  recommendation?: RecommendationBlock;
  referral?: ReferralBlock;
  return?: ReturnBlock;
  review?: ReviewBlock;
  search?: SearchBlock;
  shipment?: ShipmentBlock;
  subscription?: SubscriptionBlock;
  support?: SupportBlock;
  survey?: SurveyBlock;
  [field: string]: unknown;
}

